function newTask(){task={id:token(),revision:1,round:1,destination:'claude',purpose:'定位应用连接数据库失败的原因，给出排查步骤。',sources:[],released:[],followup:false,expires:Date.now()+30*60000};preview=null;aliases.clear();}
function persist(){saved.records=saved.records.filter(r=>r.expires>Date.now());try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{toast('无法保存演示记录；原始材料仍不会落库');}}
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2500);}
